VFI_LOW_MEMORY = "低内存（FP16）"
VFI_MAX_COMPATIBILITY = "最高兼容（FP32）"
VFI_MEMORY_MODES = (VFI_LOW_MEMORY, VFI_MAX_COMPATIBILITY)

SAVE_TIME_DISABLED = "不使用时间（仅序号）"
SAVE_TIME_MINUTE = "年月日-时分（冲突自动编号）"
SAVE_TIME_DATE_TIME = "年-月-日_时-分-秒"
SAVE_TIME_COMPACT = "年月日_时分秒"
SAVE_TIME_DATE = "年-月-日"
SAVE_TIME_CLOCK = "时-分-秒"
SAVE_TIME_FORMATS = (
    SAVE_TIME_DISABLED,
    SAVE_TIME_MINUTE,
    SAVE_TIME_DATE_TIME,
    SAVE_TIME_COMPACT,
    SAVE_TIME_DATE,
    SAVE_TIME_CLOCK,
)

_SAVE_TIME_PATTERNS = {
    SAVE_TIME_MINUTE: "%Y%m%d-%H%M",
    SAVE_TIME_DATE_TIME: "%Y-%m-%d_%H-%M-%S",
    SAVE_TIME_COMPACT: "%Y%m%d_%H%M%S",
    SAVE_TIME_DATE: "%Y-%m-%d",
    SAVE_TIME_CLOCK: "%H-%M-%S",
}


def _frame_indices(seconds: float, fps: float, frame_count: int) -> list[int]:
    seconds = float(seconds)
    fps = float(fps)
    if not math.isfinite(seconds) or seconds <= 0:
        raise ValueError("视频秒数必须大于 0")
    if not math.isfinite(fps) or fps <= 0:
        raise ValueError("视频 FPS 必须大于 0")
    if frame_count <= 0:
        raise ValueError("视频没有可导出的帧")
    return [
        index
        for second in range(math.ceil(seconds))
        for index in [math.floor(second * fps)]
        if index < frame_count
    ]


def _custom_frame_indices(positions: str, frame_count: int) -> list[int]:
    """Parse explicit zero-based frame positions, preserving request order."""
    if frame_count <= 0 or positions is None:
        return []
    text = str(positions).strip()
    if not text:
        return []

    indices: list[int] = []
    seen: set[int] = set()
    for token in text.replace("，", ",").split(","):
        token = token.strip()
        if not token:
            continue
        try:
            index = int(token)
        except (TypeError, ValueError) as error:
            raise ValueError(f"自定义帧位置必须是逗号分隔的非负整数：{token}") from error
        if index < 0:
            raise ValueError(f"自定义帧位置不能为负数：{index}")
        if index < frame_count and index not in seen:
            indices.append(index)
            seen.add(index)
    return indices


def _vfi_chunk_ranges(frame_count: int, chunk_frames: int) -> list[tuple[int, int]]:
    """Split frames into overlapping ranges so every adjacent pair is processed once."""
    if frame_count < 2:
        raise ValueError("帧插值至少需要两帧视频")

    chunk_frames = max(2, int(chunk_frames))
    ranges = []
    start = 0
    while start < frame_count - 1:
        stop = min(frame_count, start + chunk_frames)
        ranges.append((start, stop))
        start = stop - 1
    return ranges


def _save_video_filename(
    filename: str,
    counter: int,
    extension: str,
    time_format: str,
    now: datetime | None = None,
    output_folder: str | None = None,
) -> str:
    pattern = _SAVE_TIME_PATTERNS.get(str(time_format))
    if pattern is None:
        return f"{filename}_{counter:05}_.{extension}"

    timestamp = (now or datetime.now()).strftime(pattern)
    if str(time_format) == SAVE_TIME_MINUTE:
        base = f"{filename}_{timestamp}"
        output_file = f"{base}.{extension}"
        if not output_folder:
            return output_file
        suffix = 2
        while os.path.exists(os.path.join(output_folder, output_file)):
            output_file = f"{base}-{suffix}.{extension}"
            suffix += 1
        return output_file
    return f"{filename}_{timestamp}_{counter:05}_.{extension}"


class QQVideoBlackIntro:
    CATEGORY = "QQ/视频连续性与处理"
    FUNCTION = "blacken"
    RETURN_TYPES = ("VIDEO",)
    RETURN_NAMES = ("视频",)
    DESCRIPTION = "将视频开头指定秒数替换为纯黑帧，同时保留原 FPS、音频、元数据、分辨率和位深。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "video": ("VIDEO",),
                "seconds": (
                    "FLOAT",
                    {"default": 0.05, "min": 0.0, "max": 3600.0, "step": 0.01},
                ),
            }
        }

    @staticmethod
    def blacken(video, seconds):
        components = components_for_video(video)
        frames = components.images
        if not isinstance(frames, torch.Tensor) or frames.ndim < 1 or frames.shape[0] == 0:
            raise ValueError("视频至少需要包含一帧")

        duration = float(seconds)
        frame_rate = float(getattr(components, "frame_rate", 0.0) or 0.0)
        if not math.isfinite(duration) or duration < 0:
            raise ValueError("黑屏时长必须是大于等于 0 的有效数字")
        if not math.isfinite(frame_rate) or frame_rate <= 0:
            raise ValueError("视频 FPS 必须大于 0")

        black_count = min(int(frames.shape[0]), math.ceil(duration * frame_rate))
        if black_count <= 0:
            return (video,)

        output_frames = torch.cat((torch.zeros_like(frames[:black_count]), frames[black_count:]), dim=0)
        output_components = make_video_components(
            output_frames,
            audio=getattr(components, "audio", None),
            frame_rate=getattr(components, "frame_rate", None),
            metadata=getattr(components, "metadata", None),
            alpha=getattr(components, "alpha", None),
        )
        return (make_video_from_components(video, output_components),)


class QQVfiX2:
    CATEGORY = "QQ/视频连续性与处理"
    FUNCTION = "interpolate"
    RETURN_TYPES = ("VIDEO", "FLOAT")
    RETURN_NAMES = ("视频", "帧率")
    DESCRIPTION = (
        "使用已安装的 WhiteRabbit RIFE 4.7 分块补帧，将视频帧率加倍并保持分辨率、音频和时长。"
        "低内存模式仅降低结果缓存精度，RIFE 仍使用 FP32 计算。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "video": ("VIDEO",),
                "memory_mode": (
                    list(VFI_MEMORY_MODES),
                    {
                        "default": VFI_LOW_MEMORY,
                        "tooltip": (
                            "低内存使用 FP16 保存补帧结果，适合长视频；最高兼容使用 FP32，"
                            "适合补帧后继续进行对精度敏感的处理。"
                        ),
                    },
                ),
                "chunk_frames": (
                    "INT",
                    {
                        "default": 96,
                        "min": 2,
                        "max": 240,
                        "step": 1,
                        "tooltip": "每块输入帧数。数值越小越省临时内存，数值越大通常越快。",
                    },
                ),
            }
        }

    @staticmethod
    def interpolate(video, memory_mode=VFI_LOW_MEMORY, chunk_frames=96):
        rife_class = comfy_nodes.NODE_CLASS_MAPPINGS.get("RIFE_VFI_Opt")
        if rife_class is None:
            raise RuntimeError(
                "QQ-视频补帧×2 需要 WhiteRabbit 的 RIFE_VFI_Opt 节点和 rife47.pth 模型。"
            )

        components = components_for_video(video)
        frames = components.images
        if not isinstance(frames, torch.Tensor) or frames.ndim < 1 or frames.shape[0] < 2:
            raise ValueError("帧插值至少需要两帧视频")
        source_fps = float(getattr(components, "frame_rate", 0.0) or 0.0)
        if not math.isfinite(source_fps) or source_fps <= 0:
            raise ValueError("视频 FPS 必须大于 0")

        if memory_mode not in VFI_MEMORY_MODES:
            raise ValueError(f"不支持的 VFI 内存模式：{memory_mode}")
        output_dtype = torch.float16 if memory_mode == VFI_LOW_MEMORY else torch.float32
        frame_count = int(frames.shape[0])
        output_frame_count = frame_count * 2
        ranges = _vfi_chunk_ranges(frame_count, chunk_frames)

        try:
            interpolated = torch.empty(
                (output_frame_count, *frames.shape[1:]),
                dtype=output_dtype,
                device="cpu",
            )
        except RuntimeError as error:
            gib = output_frame_count * math.prod(frames.shape[1:]) * torch.empty(
                (), dtype=output_dtype
            ).element_size() / (1024**3)
            raise RuntimeError(
                f"QQ-视频补帧×2 无法分配约 {gib:.2f} GiB 的最终视频缓存。"
                "请使用低内存模式，或降低输入分辨率/时长。"
            ) from error

        rife_node = rife_class()
        write_index = 0
        print(
            f"[QQ-视频补帧×2] 分块补帧开始：{frame_count} -> {output_frame_count} 帧，"
            f"{len(ranges)} 块，{memory_mode}"
        )
        for start, stop in ranges:
            chunk_output, = rife_node.vfi(
                ckpt_name="rife47.pth",
                frames=frames[start:stop],
                multiplier=2,
                scale_factor=1.0,
                ensemble=False,
                clear_cache_after_n_frames=10,
            )

            # 每块只写入相邻帧对产生的“原帧 + 中间帧”；末帧交给下一块，避免边界重复。
            pair_output_count = 2 * (stop - start - 1)
            if int(chunk_output.shape[0]) < pair_output_count:
                raise RuntimeError(
                    "WhiteRabbit RIFE 返回的帧数少于预期："
                    f"需要至少 {pair_output_count} 帧，实际 {int(chunk_output.shape[0])} 帧。"
                )
            chunk_pairs = chunk_output[:pair_output_count]
            if tuple(chunk_pairs.shape[1:]) != tuple(frames.shape[1:]):
                raise RuntimeError(
                    "WhiteRabbit RIFE 改变了视频尺寸，无法合并分块："
                    f"输入 {tuple(frames.shape[1:])}，输出 {tuple(chunk_pairs.shape[1:])}。"
                )
            interpolated[write_index : write_index + pair_output_count].copy_(chunk_pairs)
            write_index += pair_output_count
            del chunk_pairs, chunk_output

        # 最后原帧写入两次，使 N 帧@FPS 精确对应 2N 帧@2FPS，且不再复制完整输出。
        if write_index != output_frame_count - 2:
            raise RuntimeError(
                f"QQ-视频补帧×2 分块帧数异常：已写入 {write_index}，预期 {output_frame_count - 2}。"
            )
        interpolated[-2:].copy_(
            frames[-1:].to(device="cpu", dtype=output_dtype).expand_as(interpolated[-2:])
        )
        print(f"[QQ-视频补帧×2] 分块补帧完成：{output_frame_count} 帧")

        output_fps = source_fps * 2.0
        output_components = make_video_components(
            interpolated,
            audio=getattr(components, "audio", None),
            frame_rate=Fraction(round(output_fps * 1000), 1000),
            metadata=getattr(components, "metadata", None),
            alpha=getattr(components, "alpha", None),
        )
        return make_video_from_components(video, output_components), output_fps


class QQSaveVideo:
    CATEGORY = "QQ/视频连续性与处理"
    FUNCTION = "save"
    RETURN_TYPES = ("VIDEO", "IMAGE", "IMAGE", "IMAGE")
    RETURN_NAMES = ("视频", "每秒首帧", "最后一帧", "自定义帧")
    OUTPUT_NODE = True
    DESCRIPTION = "保存视频，并输出每秒第一帧、视频最后一帧和手动指定的关键帧。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "video": ("VIDEO",),
                "seconds": ("FLOAT", {"default": 5.0, "min": 0.01, "max": 86400.0, "step": 0.01}),
                "fps": ("FLOAT", {"forceInput": True}),
                "自定义帧位置": (
                    "STRING",
                    {
                        "default": "",
                        "multiline": False,
                        "tooltip": "输入从 0 开始的帧索引，用逗号分隔，例如：0,24,48。",
                    },
                ),
                "filename_prefix": ("STRING", {"default": "video/Wsl", "multiline": False}),
                "format": (["auto", "mp4"], {"default": "auto"}),
                "codec": (["auto", "h264"], {"default": "auto"}),
                "time_format": (SAVE_TIME_FORMATS, {"default": SAVE_TIME_DISABLED}),
            },
            "hidden": {"prompt": "PROMPT", "extra_pnginfo": "EXTRA_PNGINFO"},
        }

    @staticmethod
    def save(
        video,
        seconds,
        fps,
        filename_prefix,
        format,
        codec,
        time_format=SAVE_TIME_DISABLED,
        自定义帧位置="",
        prompt=None,
        extra_pnginfo=None,
    ):
        components = components_for_video(video)
        frames = components.images
        if not isinstance(frames, torch.Tensor) or frames.shape[0] == 0:
            raise ValueError("连接的视频没有可保存的帧")
        source_fps = float(fps or getattr(components, "frame_rate", 0.0) or 0.0)
        indexes = _frame_indices(seconds, source_fps, int(frames.shape[0]))
        sampled_frames = frames[indexes]
        last_frame = frames[-1:]
        custom_indexes = _custom_frame_indices(自定义帧位置, int(frames.shape[0]))
        custom_frames = frames[custom_indexes] if custom_indexes else frames[:0]

        width, height = video.get_dimensions()
        output_folder, filename, counter, subfolder, _ = folder_paths.get_save_image_path(
            filename_prefix,
            folder_paths.get_output_directory(),
            width,
            height,
        )
        metadata = None
        if not args.disable_metadata:
            metadata_items = {}
            if extra_pnginfo is not None:
                metadata_items.update(extra_pnginfo)
            if prompt is not None:
                metadata_items["prompt"] = prompt
            if metadata_items:
                metadata = metadata_items

        extension = Types.VideoContainer.get_extension(format)
        output_file = _save_video_filename(
            filename,
            counter,
            extension,
            time_format,
            output_folder=output_folder,
        )
        video.save_to(
            os.path.join(output_folder, output_file),
            format=Types.VideoContainer(format),
            codec=str(codec),
            metadata=metadata,
        )
        return {
            "ui": {
                # ComfyUI's legacy preview protocol renders video files from
                # the standard ``images`` field when ``animated`` is true.
                # ``wsl_saved_video`` is a private key and is ignored by the
                # frontend, so it leaves this output node without a preview.
                "images": [
                    {"filename": output_file, "subfolder": subfolder, "type": "output"}
                ],
                "animated": (True,),
            },
            "result": (video, sampled_frames, last_frame, custom_frames),
        }


